const NEARBY_CATEGORIES = [
  { key: "schools", label: "Schools", icon: "\u{1F3EB}", names: ["Capital Science Academy", "Riverside International School", "Hilltop Montessori"] },
  { key: "hospitals", label: "Hospitals", icon: "\u{1F3E5}", names: ["Trust Care Hospital", "District General Clinic", "Wellness Medical Centre"] },
  { key: "restaurants", label: "Restaurants", icon: "\u{1F37D}\uFE0F", names: ["The Grill House", "Savannah Kitchen", "Caf\u00e9 Meridian"] },
  { key: "shopping", label: "Shopping centres", icon: "\u{1F6CD}\uFE0F", names: ["City Mall", "District Plaza", "Green Market Square"] },
  { key: "transport", label: "Transportation", icon: "\u{1F68C}", names: ["Main Road Bus Stop", "Metro Link Station", "District Taxi Park"] },
];

function getNearbyPlaces(property) {
  const rand = seededRandom(property.id * 331 + 7);
  return NEARBY_CATEGORIES.map((c) => ({
    ...c,
    distanceKm: (0.4 + rand() * 3.2).toFixed(1),
    name: c.names[Math.floor(rand() * c.names.length)],
  }));
}

