export default function DoxxaRentals() {
  const [view, setView] = useState({ name: "home" });
  const [saved, setSaved] = useState([]);
  const [compareIds, setCompareIds] = useState([]);
  const [navQuery, setNavQuery] = useState("");
  const [searchQuery, setSearchQuery] = useState("");
  // Session-only premium unlock state: { [propertyId]: unlockedAtTimestamp }.
  // A real deployment persists this server-side per user so the 30-day access
  // window survives reloads/devices; artifacts can't use localStorage, so this
  // resets on refresh here.
  const [premiumUnlocked, setPremiumUnlocked] = useState({});

  const toggleSave = (id) => setSaved((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  const toggleCompare = (id) =>
    setCompareIds((c) => {
      if (c.includes(id)) return c.filter((x) => x !== id);
      if (c.length >= 3) return c;
      return [...c, id];
    });

  const openProperty = (id) => setView({ name: "detail", id });
  const openAgent = (id) => setView({ name: "agent", id });
  const openDistrict = (key) => setView({ name: "district", key });
  const openCategory = (districtKey, categoryKey) => setView({ name: "district-listings", districtKey, categoryKey });
  const isUnlocked = (id) => {
    const ts = premiumUnlocked[id];
    if (!ts) return false;
    return Date.now() - ts < PREMIUM_ACCESS_DAYS * 24 * 60 * 60 * 1000;
  };
  const startCheckout = (id) => setView({ name: "checkout", id });
  const markPaid = (id) => {
    setPremiumUnlocked((m) => ({ ...m, [id]: Date.now() }));
    setView({ name: "premium-success", id });
  };

  useEffect(() => {
    window.__doxxaOpen = openProperty;
    return () => {
      delete window.__doxxaOpen;
    };
  }, []);

  return (
    <div className="min-h-screen bg-neutral-950" style={{ fontFamily: "system-ui, -apple-system, sans-serif" }}>
      <style>{`
        @keyframes doxxaFadeUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes doxxaFloatY { 0% { transform: translateY(0); } 50% { transform: translateY(-6px); } 100% { transform: translateY(0); } }
        .doxxa-fade-up { animation: doxxaFadeUp 0.7s cubic-bezier(0.16, 1, 0.3, 1) both; }
        .doxxa-float { animation: doxxaFloatY 6s ease-in-out infinite; }
        .doxxa-glass { backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); background: rgba(23, 23, 23, 0.55); border: 1px solid rgba(255, 255, 255, 0.08); }
        .doxxa-card-premium { transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s ease, border-color 0.35s ease; will-change: transform; }
        .doxxa-card-premium:hover { transform: translateY(-6px); box-shadow: 0 24px 48px -16px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(245, 194, 76, 0.12), 0 8px 24px -8px rgba(245, 194, 76, 0.08); }
      `}</style>
      <Navbar
        view={view}
        setView={setView}
        savedCount={saved.length}
        compareCount={compareIds.length}
        query={navQuery}
        setQuery={setNavQuery}
        onSearch={() => {
          setSearchQuery(navQuery);
          setView({ name: "search" });
        }}
      />
      {view.name === "home" && (
        <Home setView={setView} onOpenProperty={openProperty} onOpenSearch={() => setView({ name: "search" })} onOpenDistrict={openDistrict} />
      )}
      {view.name === "district" && (
        <DistrictPage districtKey={view.key} onBack={() => setView({ name: "home" })} onOpenCategory={openCategory} />
      )}
      {view.name === "district-listings" && (
        <DistrictCategoryListings
          districtKey={view.districtKey}
          categoryKey={view.categoryKey}
          onBack={() => openDistrict(view.districtKey)}
          onBackHome={() => setView({ name: "home" })}
          onOpenProperty={openProperty}
          saved={saved}
          toggleSave={toggleSave}
          compareIds={compareIds}
          toggleCompare={toggleCompare}
        />
      )}
      {view.name === "search" && (
        <Search
          initialQuery={searchQuery}
          onOpenProperty={openProperty}
          saved={saved}
          toggleSave={toggleSave}
          compareIds={compareIds}
          toggleCompare={toggleCompare}
        />
      )}
      {view.name === "detail" && (
        <PropertyDetail
          propertyId={view.id}
          onBack={() => setView({ name: "search" })}
          onOpenAgent={openAgent}
          saved={saved}
          toggleSave={toggleSave}
          compareIds={compareIds}
          toggleCompare={toggleCompare}
          isPremiumUnlocked={isUnlocked(view.id)}
          onUnlockPremium={() => startCheckout(view.id)}
        />
      )}
      {view.name === "agent" && (
        <AgentProfile agentId={view.id} onBack={() => window.history.length && setView({ name: "search" })} onOpenProperty={openProperty} />
      )}
      {view.name === "saved" && (
        <SavedView ids={saved} onOpenProperty={openProperty} saved={saved} toggleSave={toggleSave} compareIds={compareIds} toggleCompare={toggleCompare} />
      )}
      {view.name === "compare" && (
        <CompareView ids={compareIds} toggleCompare={toggleCompare} onOpenProperty={openProperty} />
      )}
      {view.name === "about" && <AboutPage />}
      {view.name === "signup" && (
        <SignupView initialRole={view.role} onBack={() => setView({ name: "home" })} />
      )}
      {view.name === "checkout" && (
        <CheckoutView propertyId={view.id} onBack={() => setView({ name: "detail", id: view.id })} onPaid={markPaid} />
      )}
      {view.name === "premium-success" && (
        <PremiumSuccessView propertyId={view.id} onViewProperty={(id) => setView({ name: "detail", id })} />
      )}
      {view.name !== "home" && <Footer setView={setView} />}
    </div>
  );
}
